use vstd::prelude::*;

verus! {
    // Specification for the recursive count function
    spec fn count_recursive(text: &Vec<char>, n: nat) -> nat
        requires
            n <= text.len() as nat,
        decreases n,
    {
        if n == 0 {
            0
        } else {
            let last_char = text[n - 1];
            if last_char >= '0' && last_char <= '9' {
                count_recursive(text, n - 1) + 1
            } else {
                count_recursive(text, n - 1)
            }
        }
    }

    // Main function to count digits in the vector
    fn count_digits(text: &Vec<char>) -> (count: usize)
        requires
            text.len() <= usize::MAX,
        ensures
            count == count_recursive(text, text.len() as nat),
    {
        let n = text.len();
        let mut count: usize = 0;
        let mut idx: usize = 0;

        while idx < n
            invariant
                idx <= n,
                count == count_recursive(text, idx as nat),
            decreases n - idx,
        {
            let last_char = text[idx];
            if last_char >= '0' && last_char <= '9' {
                count = count + 1;
            }
            idx = idx + 1;
        }
        count
    }
}

